ac-circuits-inductive-capacitive-reactan.js:
(() => {
  'use strict';
  const fEl = document.getElementById('ac-f'), rEl = document.getElementById('ac-r');
  const lEl = document.getElementById('ac-l'), cEl = document.getElementById('ac-c');
  const zResEl = document.getElementById('ac-res-z'), rcResEl = document.getElementById('ac-res-react');

  function update() {
    const f = parseFloat(fEl.value), R = parseFloat(rEl.value);
    const L_mH = parseFloat(lEl.value), C_uF = parseFloat(cEl.value);

    if (isNaN(f) || isNaN(R) || isNaN(L_mH) || isNaN(C_uF) || f <= 0 || R < 0 || L_mH < 0 || C_uF <= 0) return;

    const L = L_mH / 1000.0;
    const C = C_uF * 1e-6;

    // Inductive reactance: X_L = 2 * pi * f * L  [Ohms]
    const X_L = 2.0 * Math.PI * f * L;
    // Capacitive reactance: X_C = 1 / ( 2 * pi * f * C )  [Ohms]
    const X_C = 1.0 / (2.0 * Math.PI * f * C);

    const netX = X_L - X_C;

    // Total impedance: Z = sqrt( R^2 + (X_L - X_C)^2 )  [Ohms]
    const Z = Math.sqrt(Math.pow(R, 2) + Math.pow(netX, 2));

    // Phase angle phi = atan( (X_L - X_C) / R ) in degrees
    const phi_rad = Math.atan2(netX, R);
    const phi_deg = (phi_rad * 180.0) / Math.PI;

    let regime = '';
    if (netX > 0.1) regime = 'INDUCTIVE (X_L > X_C: Current lags voltage by ' + phi_deg.toFixed(1) + '°)';
    else if (netX < -0.1) regime = 'CAPACITIVE (X_C > X_L: Current leads voltage by ' + Math.abs(phi_deg).toFixed(1) + '°)';
    else regime = 'PURELY RESISTIVE (Resonance: X_L = X_C, Z = R)';

    zResEl.textContent = 'Impedance Z = ' + Z.toFixed(2) + ' Ω';
    rcResEl.textContent = 'X_L = ' + X_L.toFixed(2) + ' Ω | X_C = ' + X_C.toFixed(2) + ' Ω | Net X = ' + (netX >= 0 ? '+' : '') + netX.toFixed(2) + ' Ω (' + regime + ')';
  }

  [fEl, rEl, lEl, cEl].forEach(el => el.addEventListener('input', update));
  update();
})();

ac-impedance-rlc-series-circuit-calculat.js:
(() => {
  'use strict';
  const rEl = document.getElementById('rlc-r'), lEl = document.getElementById('rlc-l');
  const cEl = document.getElementById('rlc-c'), fEl = document.getElementById('rlc-f');
  const zResEl = document.getElementById('rlc-res-z'), thResEl = document.getElementById('rlc-res-theta'), f0ResEl = document.getElementById('rlc-res-f0');

  function update() {
    const R = parseFloat(rEl.value), lMh = parseFloat(lEl.value), cUf = parseFloat(cEl.value), fHz = parseFloat(fEl.value);
    if (isNaN(R) || isNaN(lMh) || isNaN(cUf) || isNaN(fHz) || R < 0 || lMh <= 0 || cUf <= 0 || fHz <= 0) return;

    const L = lMh * 1e-3;
    const C = cUf * 1e-6;
    const omega = 2 * Math.PI * fHz;

    // Reactances: XL = omega*L, XC = 1 / (omega*C)
    const XL = omega * L;
    const XC = 1 / (omega * C);
    const Xnet = XL - XC;

    // Total Impedance Z = sqrt(R^2 + (XL - XC)^2)
    const Z = Math.sqrt(Math.pow(R, 2) + Math.pow(Xnet, 2));

    // Phase angle theta = atan(Xnet / R)
    const rad = Math.atan2(Xnet, R);
    const deg = (rad * 180) / Math.PI;

    // Resonance f0 = 1 / (2*pi*sqrt(L*C))
    const f0 = 1 / (2 * Math.PI * Math.sqrt(L * C));

    zResEl.textContent = Z.toFixed(2) + ' Ω';
    thResEl.textContent = (deg >= 0 ? '+' : '') + deg.toFixed(2) + '° (' + (deg > 0 ? 'Inductive' : (deg < 0 ? 'Capacitive' : 'Resonant')) + ')';
    f0ResEl.textContent = 'f₀ = ' + (f0 >= 1000 ? (f0 / 1000).toFixed(2) + ' kHz' : f0.toFixed(1) + ' Hz');
  }

  [rEl, lEl, cEl, fEl].forEach(el => el.addEventListener('input', update));
  update();
})();

ac-reactive-power-kvar-calculator.js:
(() => {
  'use strict';
  const kwEl = document.getElementById('kvar-kw'), pf1El = document.getElementById('kvar-pf1'), pf2El = document.getElementById('kvar-pf2');
  const capResEl = document.getElementById('kvar-res-cap'), curResEl = document.getElementById('kvar-res-curr');

  function update() {
    const P = parseFloat(kwEl.value), pf1 = parseFloat(pf1El.value), pf2 = parseFloat(pf2El.value);
    if (isNaN(P) || isNaN(pf1) || isNaN(pf2) || P <= 0 || pf1 <= 0 || pf1 >= 1 || pf2 <= pf1 || pf2 > 1.0) return;

    // theta1 = acos(pf1), theta2 = acos(pf2)
    const th1 = Math.acos(pf1);
    const th2 = Math.acos(pf2);

    // Q1 = P * tan(th1)
    const Q1 = P * Math.tan(th1);
    // Q2 = P * tan(th2)
    const Q2 = P * Math.tan(th2);
    // Q_cap = Q1 - Q2 = P * (tan(th1) - tan(th2))
    const Qcap = Q1 - Q2;

    capResEl.textContent = Qcap.toFixed(1) + ' kVAR';
    curResEl.textContent = Q1.toFixed(1) + ' kVAR (Initial)';
  }

  [kwEl, pf1El, pf2El].forEach(el => el.addEventListener('input', update));
  update();
})();

ackermann-steering-geometry-inner-outer-.js:
(() => {
  'use strict';
  const lEl = document.getElementById('ack-l'), wEl = document.getElementById('ack-w'), diEl = document.getElementById('ack-di');
  const doResEl = document.getElementById('ack-res-do'), dfResEl = document.getElementById('ack-res-diff');

  function update() {
    const L = parseFloat(lEl.value), w = parseFloat(wEl.value), delta_i_deg = parseFloat(diEl.value);
    if (isNaN(L) || isNaN(w) || isNaN(delta_i_deg) || L <= 0 || w <= 0 || delta_i_deg <= 0 || delta_i_deg >= 90) return;

    const delta_i_rad = (delta_i_deg * Math.PI) / 180;

    // True Ackermann relation: cot(delta_o) - cot(delta_i) = w / L
    // cot(delta_o) = cot(delta_i) + (w / L)
    const cot_delta_i = 1.0 / Math.tan(delta_i_rad);
    const cot_delta_o = cot_delta_i + (w / L);

    const delta_o_rad = Math.atan(1.0 / cot_delta_o);
    const delta_o_deg = (delta_o_rad * 180) / Math.PI;

    const deltaDiff = delta_i_deg - delta_o_deg;

    // Centerline turn radius R = L / tan(delta_avg)
    const R_center = L / Math.tan((delta_i_rad + delta_o_rad) / 2);

    doResEl.textContent = 'Outer Angle δ_o = ' + delta_o_deg.toFixed(1) + '° (Inner: ' + delta_i_deg + '°)';
    dfResEl.textContent = 'Toe-Out on Turn: Δδ = ' + deltaDiff.toFixed(2) + '° | Common Center Turn Radius R = ' + R_center.toFixed(2) + ' m (Zero Tire Scrub)';
  }

  [lEl, wEl, diEl].forEach(el => el.addEventListener('input', update));
  update();
})();

ackermann-steering-geometry-turning-radi.js:
(() => {
  'use strict';
  const lEl = document.getElementById('ak-l'), wEl = document.getElementById('ak-w'), dlEl = document.getElementById('ak-delta');
  const rdResEl = document.getElementById('ak-res-rad'), otResEl = document.getElementById('ak-res-outer');

  function update() {
    const L = parseFloat(lEl.value), w = parseFloat(wEl.value), delta_i_deg = parseFloat(dlEl.value);
    if (isNaN(L) || isNaN(w) || isNaN(delta_i_deg) || L <= 0 || w <= 0 || delta_i_deg <= 0 || delta_i_deg >= 85) return;

    const delta_i_rad = (delta_i_deg * Math.PI) / 180.0;

    // Ackermann formula: cot(delta_o) = cot(delta_i) + (w / L)
    const cot_delta_i = 1.0 / Math.tan(delta_i_rad);
    const cot_delta_o = cot_delta_i + (w / L);
    const delta_o_rad = Math.atan(1.0 / cot_delta_o);
    const delta_o_deg = (delta_o_rad * 180.0) / Math.PI;

    // Center turning radius R from rear axle center: R_rear = L / tan(delta_center) approx L / tan((delta_i + delta_o)/2)
    const delta_avg = (delta_i_rad + delta_o_rad) / 2.0;
    const R_rear = L / Math.tan(delta_avg);
    const R_center = Math.sqrt(Math.pow(R_rear, 2) + Math.pow(L / 2.0, 2));

    rdResEl.textContent = 'Turning Radius R = ' + R_center.toFixed(2) + ' m (Diameter ' + (R_center * 2).toFixed(1) + ' m)';
    otResEl.textContent = 'Outer Wheel δ_o = ' + delta_o_deg.toFixed(1) + '° (Inner δ_i = ' + delta_i_deg.toFixed(1) + '°: Δδ = ' + (delta_i_deg - delta_o_deg).toFixed(1) + '° Difference)';
  }

  [lEl, wEl, dlEl].forEach(el => el.addEventListener('input', update));
  update();
})();

acoustic-coincidence-critical-frequency-.js:
(() => {
  'use strict';
  const matEl = document.getElementById('coin-mat'), thkEl = document.getElementById('coin-thk');
  const fcResEl = document.getElementById('coin-res-fc'), dResEl = document.getElementById('coin-res-desc');

  const c_sound = 343.0; // m / s

  const PANELS = {
    'glass':    { E_gpa: 70.0,  rho: 2500.0, nu: 0.22, name: 'Float Glass' },
    'gypsum':   { E_gpa: 2.5,   rho: 800.0,  nu: 0.30, name: 'Gypsum Drywall' },
    'steel':    { E_gpa: 200.0, rho: 7850.0, nu: 0.28, name: 'Sheet Steel' },
    'aluminum': { E_gpa: 70.0,  rho: 2700.0, nu: 0.33, name: 'Sheet Aluminum' },
    'plywood':  { E_gpa: 6.0,   rho: 600.0,  nu: 0.25, name: 'Plywood Wood' }
  };

  function update() {
    const p = PANELS[matEl.value];
    const tMm = parseFloat(thkEl.value);

    if (isNaN(tMm) || tMm <= 0) return;

    const tM = tMm * 1e-3;
    const E_pa = p.E_gpa * 1e9;

    // Bending stiffness per unit width B = E * t^3 / ( 12 * (1 - nu^2) )  [N * m]
    const B = (E_pa * Math.pow(tM, 3)) / (12.0 * (1.0 - Math.pow(p.nu, 2)));

    // Surface mass density m = rho * t  [kg / m^2]
    const massDensity = p.rho * tM;

    // Critical coincidence frequency: f_c = ( c^2 / (2 * pi) ) * sqrt( m / B )  [Hz]
    const f_c = (Math.pow(c_sound, 2) / (2 * Math.PI)) * Math.sqrt(massDensity / B);

    fcResEl.textContent = 'f_c = ' + Math.round(f_c).toLocaleString() + ' Hz Coincidence Dip';
    dResEl.textContent = p.name + ' (' + tMm + ' mm: Surface Mass m = ' + massDensity.toFixed(1) + ' kg/m², Bending Stiffness B = ' + B.toFixed(1) + ' N·m)';
  }

  matEl.addEventListener('change', update);
  thkEl.addEventListener('input', update);
  update();
})();

