    const isMale = gEl.value === 'male';
    const actWt = parseFloat(wEl.value), hCm = parseFloat(hEl.value);
    if (isNaN(actWt) || isNaN(hCm) || actWt <= 0 || hCm <= 100) return;

    const hInches = hCm / 2.54;
