      adjBw = ibw + 0.4 * (actWt - ibw);
    }

    const pctOfIbw = (actWt / ibw) * 100;

    adjEl.textContent = adjBw.toFixed(1) + ' kg (' + (adjBw * 2.20462).toFixed(1) + ' lbs)';
