    arResEl.textContent = 'Aspect Ratio AR = ' + AR.toFixed(2);
    cdiResEl.textContent = 'Induced Drag C_Di = ' + C_Di.toFixed(4) + ' (Oswald e = ' + e + ' @ C_L = ' + C_L + ')';
  }

  [bEl, sEl, clEl, eEl].forEach(el => el.addEventListener('input', update));
  update();
})();

