    // Alveolar Gas Equation: P_A_O2 = FiO2 * (Patm - PH2O) - (PaCO2 / RQ)  [mmHg]
    const P_A_O2 = (FiO2 * (Patm - PH2O)) - (PaCO2 / RQ);

    // A-a Gradient: A-a = P_A_O2 - PaO2
    const Aa_gradient = P_A_O2 - PaO2;

    // Age-adjusted expected normal upper limit: (Age / 4) + 4
