    paResEl.textContent = 'Alveolar P_A O₂ = ' + P_A_O2.toFixed(1) + ' mmHg | Age ' + age + ' Expected Upper Limit ≤ ' + normal_Aa_limit.toFixed(1) + ' mmHg [FiO₂=' + FiO2 + ']';
  }

