  const zEl = document.getElementById('as-z'), hEl = document.getElementById('as-h');
  const rh0El = document.getElementById('as-rho0'), p0El = document.getElementById('as-p0');
  const rhResEl = document.getElementById('as-res-rho'), pResEl = document.getElementById('as-res-p');

  function update() {
    const z_km = parseFloat(zEl.value), H_km = parseFloat(hEl.value);
    const rho0 = parseFloat(rh0El.value), p0_kPa = parseFloat(p0El.value);

    if (isNaN(z_km) || isNaN(H_km) || isNaN(rho0) || isNaN(p0_kPa) || z_km < 0 || H_km <= 0 || rho0 <= 0 || p0_kPa <= 0) return;

    const exponent = - z_km / H_km;
    const factor = Math.exp(exponent);
    const rho_z = rho0 * factor;
    const p_z_kPa = p0_kPa * factor;
    const p_z_mbar = p_z_kPa * 10.0;
    const pct_surface = factor * 100.0;

    rhResEl.textContent = 'Air Density ρ = ' + rho_z.toFixed(3) + ' kg / m³ (' + pct_surface.toFixed(1) + '% Sea Level)';
    pResEl.textContent = 'Pressure p = ' + p_z_kPa.toFixed(2) + ' kPa (' + Math.round(p_z_mbar) + ' mbar) | z = ' + z_km + ' km (' + (z_km/H_km).toFixed(2) + ' e-folds @ H=' + H_km + ' km)';
  }

  [zEl, hEl, rh0El, p0El].forEach(el => el.addEventListener('input', update));
  update();
})();

atmospheric-scale-height-barometric-expo.js:
(() => {
  'use strict';
  const zEl = document.getElementById('at-z'), plEl = document.getElementById('at-planet');
  const pResEl = document.getElementById('at-res-p'), dsResEl = document.getElementById('at-res-desc');

  function update() {
    const z_km = parseFloat(zEl.value);
    const parts = plEl.value.split('_');
    const H_km = parseFloat(parts[0]);
    const P0_kPa = parseFloat(parts[1]);

    if (isNaN(z_km) || isNaN(H_km) || isNaN(P0_kPa) || z_km < 0) return;

    // Barometric formula: P(z) = P0 * exp( -z / H )
    const P_z = P0_kPa * Math.exp(-z_km / H_km);
    const frac = (P_z / P0_kPa) * 100.0;

    let note = '';
    let color = '#22543d';

    if (frac < 40.0) {
      note = 'EXTREME HYPOXIA / DEATH ZONE: Supplementary oxygen mandatory for humans';
      color = '#c53030';
    } else if (frac < 75.0) {
      note = 'HIGH ALTITUDE (Reduced air density: Aircraft cruising altitude regime)';
      color = '#ea580c';
    } else {
      note = 'HABITABLE SURFACE REGIME';
      color = '#22543d';
    }

    pResEl.textContent = 'P = ' + (P_z >= 100 ? P_z.toFixed(1) : P_z.toFixed(2)) + ' kPa (' + (P_z / 101.325).toFixed(3) + ' atm)';
    pResEl.style.color = color;
    dsResEl.textContent = note + ' (Scale Height H = ' + H_km + ' km | Pressure = ' + frac.toFixed(1) + '% of surface @ z = ' + z_km + ' km)';
    dsResEl.style.color = color;
  }

  zEl.addEventListener('input', update);
  plEl.addEventListener('change', update);
  update();
})();

