(() => {
  'use strict';
  const x1El = document.getElementById('bz-x1'), y1El = document.getElementById('bz-y1');
  const x2El = document.getElementById('bz-x2'), y2El = document.getElementById('bz-y2'), tEl = document.getElementById('bz-t');
  const pResEl = document.getElementById('bz-res-pt'), tgResEl = document.getElementById('bz-res-tang');

  const P0 = { x: 0.0, y: 0.0 };
  const P3 = { x: 1.0, y: 1.0 };

  function update() {
    const x1 = parseFloat(x1El.value), y1 = parseFloat(y1El.value);
    const x2 = parseFloat(x2El.value), y2 = parseFloat(y2El.value), t = parseFloat(tEl.value);

    if (isNaN(x1) || isNaN(y1) || isNaN(x2) || isNaN(y2) || isNaN(t) || t < 0 || t > 1) return;

    const u = 1 - t;
    const Bx = (Math.pow(u, 3) * P0.x) + (3 * Math.pow(u, 2) * t * x1) + (3 * u * Math.pow(t, 2) * x2) + (Math.pow(t, 3) * P3.x);
    const By = (Math.pow(u, 3) * P0.y) + (3 * Math.pow(u, 2) * t * y1) + (3 * u * Math.pow(t, 2) * y2) + (Math.pow(t, 3) * P3.y);

    const dBx = (3 * Math.pow(u, 2) * (x1 - P0.x)) + (6 * u * t * (x2 - x1)) + (3 * Math.pow(t, 2) * (P3.x - x2));
    const dBy = (3 * Math.pow(u, 2) * (y1 - P0.y)) + (6 * u * t * (y2 - y1)) + (3 * Math.pow(t, 2) * (P3.y - y2));
    const slope = dBx !== 0 ? (dBy / dBx) : 9999;

    pResEl.textContent = 'B(' + t.toFixed(2) + ') = (' + Bx.toFixed(3) + ', ' + By.toFixed(3) + ')';
    tgResEl.textContent = 'Tangent: (' + dBx.toFixed(3) + ', ' + dBy.toFixed(3) + ') | Slope m = ' + slope.toFixed(3) + ' (Angle: ' + ((Math.atan2(dBy, dBx) * 180) / Math.PI).toFixed(1) + '°)';
  }

  [x1El, y1El, x2El, y2El, tEl].forEach(el => el.addEventListener('input', update));
  update();
})();

bi-elliptic-transfer-delta-v-hohmann-com.js:
(() => {
  'use strict';
  const r1El = document.getElementById('bi-r1'), r2El = document.getElementById('bi-r2'), rbEl = document.getElementById('bi-rb');
  const dvResEl = document.getElementById('bi-res-dv'), svResEl = document.getElementById('bi-res-save');

  const mu = 398600.4418; // Earth gravitational parameter in km^3 / s^2

  function update() {
    const r1 = parseFloat(r1El.value), r2 = parseFloat(r2El.value), rb = parseFloat(rbEl.value);
    if (isNaN(r1) || isNaN(r2) || isNaN(rb) || r1 <= 0 || r2 <= r1 || rb <= r2) return;

    const ratio = r2 / r1;

    // Hohmann transfer 2-burn delta-V:
    // a_hoh = (r1 + r2) / 2
    // dv1_hoh = sqrt(mu/r1) * ( sqrt(2*r2 / (r1 + r2)) - 1 )
    // dv2_hoh = sqrt(mu/r2) * ( 1 - sqrt(2*r1 / (r1 + r2)) )
    const dv1_hoh = Math.sqrt(mu / r1) * (Math.sqrt((2.0 * r2) / (r1 + r2)) - 1.0);
    const dv2_hoh = Math.sqrt(mu / r2) * (1.0 - Math.sqrt((2.0 * r1) / (r1 + r2)));
    const dv_hohmann = dv1_hoh + dv2_hoh;

    // Bi-elliptic transfer 3-burn delta-V:
    // Burn 1 (at r1): dv1 = sqrt(2*mu/r1 - 2*mu/(r1+rb)) - sqrt(mu/r1)
    const dv1_bi = Math.sqrt((2.0 * mu / r1) - (2.0 * mu / (r1 + rb))) - Math.sqrt(mu / r1);
    // Burn 2 (at rb): dv2 = sqrt(2*mu/rb - 2*mu/(r2+rb)) - sqrt(2*mu/rb - 2*mu/(r1+rb))
    const dv2_bi = Math.abs(Math.sqrt((2.0 * mu / rb) - (2.0 * mu / (r2 + rb))) - Math.sqrt((2.0 * mu / rb) - (2.0 * mu / (r1 + rb))));
    // Burn 3 (at r2): dv3 = sqrt(mu/r2) - sqrt(2*mu/r2 - 2*mu/(r2+rb))
    const dv3_bi = Math.abs(Math.sqrt(mu / r2) - Math.sqrt((2.0 * mu / r2) - (2.0 * mu / (r2 + rb))));

    const dv_bielliptic = dv1_bi + dv2_bi + dv3_bi;
    const diff_m_s = (dv_hohmann - dv_bielliptic) * 1000.0;

    let evalStr = '';
    let color = '#22543d';

    if (ratio > 11.94 && dv_bielliptic < dv_hohmann) {
      evalStr = 'BI-ELLIPTIC IS MORE EFFICIENT (Saves +' + Math.round(diff_m_s) + ' m/s over Hohmann | r₂/r₁ = ' + ratio.toFixed(1) + ' > 11.94)';
      color = '#22543d';
    } else {
      evalStr = 'HOHMANN IS MORE EFFICIENT (Hohmann saves +' + Math.round(-diff_m_s) + ' m/s and requires much shorter transfer time)';
      color = '#2563eb';
    }

    dvResEl.textContent = 'Bi-Elliptic: ' + dv_bielliptic.toFixed(2) + ' km/s vs Hohmann: ' + dv_hohmann.toFixed(2) + ' km/s';
    svResEl.textContent = evalStr;
    svResEl.style.color = color;
  }

  [r1El, r2El, rbEl].forEach(el => el.addEventListener('input', update));
  update();
})();

bi-elliptic-transfer-orbit-delta-v-ratio.js:
(() => {
  'use strict';
  const r1El = document.getElementById('be-r1'), r2El = document.getElementById('be-r2');
  const rbEl = document.getElementById('be-rb'), muEl = document.getElementById('be-mu');
  const dvResEl = document.getElementById('be-res-dv'), cpResEl = document.getElementById('be-res-comp');

  function update() {
    const r1 = parseFloat(r1El.value), r2 = parseFloat(r2El.value);
    const rb = parseFloat(rbEl.value), mu = parseFloat(muEl.value);

    if (isNaN(r1) || isNaN(r2) || isNaN(rb) || isNaN(mu) || r1 <= 0 || r2 <= 0 || rb <= r2 || mu <= 0) return;

    const v_circ_1 = Math.sqrt(mu / r1);
    const v_circ_2 = Math.sqrt(mu / r2);
    const a1 = (r1 + rb) / 2.0;
    const v_1a = Math.sqrt(mu * ((2.0 / r1) - (1.0 / a1)));
    const v_1b = Math.sqrt(mu * ((2.0 / rb) - (1.0 / a1)));
    const delta_v1 = v_1a - v_circ_1;
    const a2 = (r2 + rb) / 2.0;
    const v_2b = Math.sqrt(mu * ((2.0 / rb) - (1.0 / a2)));
    const v_2r2 = Math.sqrt(mu * ((2.0 / r2) - (1.0 / a2)));
    const delta_v2 = Math.abs(v_2b - v_1b);
    const delta_v3 = Math.abs(v_circ_2 - v_2r2);
    const bi_elliptic_dv = delta_v1 + delta_v2 + delta_v3;

    const a_hoh = (r1 + r2) / 2.0;
    const hoh_v1 = Math.sqrt(mu * ((2.0 / r1) - (1.0 / a_hoh))) - v_circ_1;
    const hoh_v2 = v_circ_2 - Math.sqrt(mu * ((2.0 / r2) - (1.0 / a_hoh)));
    const hohmann_dv = hoh_v1 + hoh_v2;
    const ratio = r2 / r1;
    const diff_mps = (hohmann_dv - bi_elliptic_dv) * 100.0;

    let qual = '', color = '#22543d';
    if (diff_mps > 0) {
      qual = 'BI-ELLIPTIC IS MORE EFFICIENT (Saves ' + Math.round(diff_mps) + ' m/s over Hohmann ✓)';
      color = '#22543d';
    } else {
      qual = 'HOHMANN IS MORE EFFICIENT (Hohmann saves ' + Math.round(-diff_mps) + ' m/s)';
      color = '#ea580c';
    }

    dvResEl.textContent = 'Bi-Elliptic Δv = ' + bi_elliptic_dv.toFixed(3) + ' km / s';
    dvResEl.style.color = color;
    cpResEl.textContent = 'Hohmann Δv = ' + hohmann_dv.toFixed(3) + ' km/s | ' + qual + ' (r₂/r₁ = ' + ratio.toFixed(2) + ' @ r_b = ' + rb.toLocaleString() + ' km)';
  }

  [r1El, r2El, rbEl, muEl].forEach(el => el.addEventListener('input', update));
  update();
})();

