(() => {
  'use strict';
  const vbeEl = document.getElementById('bj-vbe'), vceEl = document.getElementById('bj-vce');
  const isEl = document.getElementById('bj-is'), vaEl = document.getElementById('bj-va'), btEl = document.getElementById('bj-beta');
  const icResEl = document.getElementById('bj-res-ic'), smResEl = document.getElementById('bj-res-small');

  const V_t = 0.02585; // Thermal voltage @ 300 K in Volts

  function update() {
    const V_BE = parseFloat(vbeEl.value), V_CE = parseFloat(vceEl.value);
    const I_S_fA = parseFloat(isEl.value), V_A = parseFloat(vaEl.value), beta = parseFloat(btEl.value);

    if (isNaN(V_BE) || isNaN(V_CE) || isNaN(I_S_fA) || isNaN(V_A) || isNaN(beta) || I_S_fA <= 0 || V_A <= 0 || beta <= 0) return;

    const I_S_A = I_S_fA * 1e-15;

    // Ebers-Moll forward active current with Early effect:
    // I_C = I_S * exp( V_BE / V_t ) * ( 1 + V_CE / V_A )  [Amperes]
    const exp_term = Math.exp(V_BE / V_t);
    const early_factor = 1.0 + (V_CE / V_A);
    const I_C_A = I_S_A * exp_term * early_factor;
    const I_C_mA = I_C_A * 1000.0;

    // Base current: I_B = I_C / beta  [uA]
    const I_B_uA = (I_C_A / beta) * 1e6;

    // Small-signal transconductance: g_m = I_C / V_t  [A/V -> mS]
    const g_m_mS = (I_C_A / V_t) * 1000.0;

    // Base input resistance: r_pi = beta / g_m  [ohms]
    const r_pi_ohm = beta / (I_C_A / V_t);

    // Output resistance: r_o = (V_A + V_CE) / I_C  [kOhms]
    const r_o_kohm = ((V_A + V_CE) / I_C_A) / 1000.0;

    icResEl.textContent = 'Collector I_C = ' + I_C_mA.toFixed(2) + ' mA (g_m = ' + Math.round(g_m_mS) + ' mS)';
    smResEl.textContent = 'Base I_B = ' + I_B_uA.toFixed(1) + ' μA | r_π = ' + Math.round(r_pi_ohm) + ' Ω | Output r_o = ' + r_o_kohm.toFixed(1) + ' kΩ (V_BE=' + V_BE + ' V, V_CE=' + V_CE + ' V)';
  }

  [vbeEl, vceEl, isEl, vaEl, btEl].forEach(el => el.addEventListener('input', update));
  update();
})();

bisection-method-root-finding-error-tole.js:
(() => {
  'use strict';
  const fnEl = document.getElementById('bi-fn'), aEl = document.getElementById('bi-a'), bEl = document.getElementById('bi-b');
  const rtResEl = document.getElementById('bi-res-root'), stResEl = document.getElementById('bi-res-steps');

  function evalF(type, x) {
    if (type === 'x3_x_2') return Math.pow(x, 3) - x - 2;
    if (type === 'cos_x') return Math.cos(x) - x;
    return Math.pow(x, 2) - 3;
  }

  function update() {
    const fnType = fnEl.value;
    let a = parseFloat(aEl.value), b = parseFloat(bEl.value);

    if (isNaN(a) || isNaN(b) || a >= b) return;

    let fa = evalF(fnType, a), fb = evalF(fnType, b);
    if (fa * fb > 0) {
      rtResEl.textContent = 'INVALID BRACKET (f(a) and f(b) have same sign)';
      stResEl.textContent = 'f(' + a + ') = ' + fa.toFixed(2) + ', f(' + b + ') = ' + fb.toFixed(2) + ' (Opposite signs required by Bolzano Theorem)';
      return;
    }

    let mid = (a + b) / 2.0;
    let iter = 0;
    const tol = 1e-4;

    while ((b - a) / 2.0 > tol && iter < 100) {
      mid = (a + b) / 2.0;
      const fmid = evalF(fnType, mid);
      if (Math.abs(fmid) < 1e-12) break;

      if (fa * fmid < 0) {
        b = mid;
        fb = fmid;
      } else {
        a = mid;
        fa = fmid;
      }
      iter++;
    }

    rtResEl.textContent = 'Root x* ≈ ' + mid.toFixed(6);
    stResEl.textContent = 'Converged in ' + iter + ' bisections (Final interval width = ' + (b - a).toExponential(2) + ' | f(x*) = ' + evalF(fnType, mid).toExponential(2) + ')';
  }

  [fnEl, aEl, bEl].forEach(el => el.addEventListener('input', update));
  fnEl.addEventListener('change', update);
  update();
})();

bishop-simplified-method-slices-slope-st.js:
(() => {
  'use strict';
  const cEl = document.getElementById('bs-c'), phiEl = document.getElementById('bs-phi');
  const wEl = document.getElementById('bs-w'), alEl = document.getElementById('bs-alpha'), ruEl = document.getElementById('bs-ru');
  const fsResEl = document.getElementById('bs-res-fs'), drResEl = document.getElementById('bs-res-drive');

  function update() {
    const c = parseFloat(cEl.value), phi_deg = parseFloat(phiEl.value);
    const W = parseFloat(wEl.value), alpha_deg = parseFloat(alEl.value), r_u = parseFloat(ruEl.value);

    if (isNaN(c) || isNaN(phi_deg) || isNaN(W) || isNaN(alpha_deg) || isNaN(r_u) || c < 0 || phi_deg < 0 || W <= 0 || alpha_deg <= 0 || r_u < 0) return;

    const phi = (phi_deg * Math.PI) / 180.0;
    const alpha = (alpha_deg * Math.PI) / 180.0;

    // Driving force: T_driving = W * sin(alpha)
    const driving = W * Math.sin(alpha);

    // Iterative solution for Bishop's FS:
    // FS = [ sum( c'*b + (W - u*b)*tan(phi) ) * 1/m_alpha ] / sum( W*sin(alpha) )
    // where m_alpha = cos(alpha) * ( 1 + tan(alpha)*tan(phi)/FS )
    let FS = 1.30;
    for (let iter = 0; iter < 10; iter++) {
      const m_alpha = Math.cos(alpha) * (1.0 + (Math.tan(alpha) * Math.tan(phi)) / FS);
      // Effective normal force: N_prime = ( W * (1 - r_u) ) / m_alpha
      const N_prime = (W * (1.0 - r_u)) / m_alpha;
      const resisting = (c * 15.0) + (N_prime * Math.tan(phi)); // 15m arc length
      FS = resisting / driving;
    }

    const resisting_total = FS * driving;

    let status = '', color = '#22543d';
    if (FS >= 1.5) { status = 'ADEQUATELY SAFE (FS ≥ 1.5)'; color = '#22543d'; }
    else if (FS >= 1.3) { status = 'ACCEPTABLE STABILITY (1.3 ≤ FS < 1.5)'; color = '#22543d'; }
    else if (FS >= 1.0) { status = 'MARGINAL (1.0 ≤ FS < 1.3)'; color = '#ea580c'; }
    else { status = 'UNSTABLE (FS < 1.0: Slope Failure)'; color = '#c53030'; }

    fsResEl.textContent = 'Bishop FS = ' + FS.toFixed(2) + ' (' + status.split(' (')[0] + ')';
    fsResEl.style.color = color;
    drResEl.textContent = 'Driving = ' + driving.toFixed(1) + ' kN | Resisting = ' + resisting_total.toFixed(1) + ' kN (r_u = ' + r_u + ')';
  }

  [cEl, phiEl, wEl, alEl, ruEl].forEach(el => el.addEventListener('input', update));
  update();
})();

