  const vinEl = document.getElementById('bjt-vin'), icEl = document.getElementById('bjt-ic');
  const bEl = document.getElementById('bjt-beta'), vbeEl = document.getElementById('bjt-vbe');
  const rbResEl = document.getElementById('bjt-res-rb'), ibResEl = document.getElementById('bjt-res-ib');

  function update() {
    const vin = parseFloat(vinEl.value), icMa = parseFloat(icEl.value);
    const beta = parseFloat(bEl.value), vbe = parseFloat(vbeEl.value);

    if (isNaN(vin) || isNaN(icMa) || isNaN(beta) || isNaN(vbe) || vin <= vbe || icMa <= 0 || beta <= 0) return;

    // Required base current I_B = I_C / beta_sat (mA)
    const ibMa = icMa / beta;
    const ibA = ibMa * 1e-3;

    // R_B = (V_in - V_BE) / I_B (Ohms)
    const rbOhms = (vin - vbe) / ibA;

    // Pick closest standard E24 resistor
    const standardE24 = [100, 120, 150, 180, 220, 270, 330, 390, 430, 470, 510, 560, 680, 750, 820, 1000, 1200, 1500, 1800, 2200, 2700, 3300, 4700, 10000];
    let bestE24 = standardE24[0];
    let minDiff = Infinity;
    for (const val of standardE24) {
      if (val <= rbOhms) { // Choose smaller or equal resistor to guarantee full saturation
        const diff = rbOhms - val;
        if (diff < minDiff) { minDiff = diff; bestE24 = val; }
      }
    }

    rbResEl.textContent = bestE24 + ' Ω (Calculated ' + Math.round(rbOhms) + ' Ω)';
    ibResEl.textContent = ibMa.toFixed(1) + ' mA (' + (vin - vbe).toFixed(2) + 'V across R_B)';
  }

  [vinEl, icEl, bEl, vbeEl].forEach(el => el.addEventListener('input', update));
  update();
})();

black-scholes-european-call-option-calcu.js:
(() => {
  'use strict';
  const sEl = document.getElementById('bs-s'), kEl = document.getElementById('bs-k');
  const tEl = document.getElementById('bs-t'), volEl = document.getElementById('bs-vol'), rEl = document.getElementById('bs-r');
  const cResEl = document.getElementById('bs-res-call'), pResEl = document.getElementById('bs-res-put');

  // Standard Normal Cumulative Distribution Function N(x) approximation
  function stdNormCdf(x) {
    const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741, a4 = -1.453152027, a5 = 1.061405429;
    const p = 0.3275911;
    const sign = x < 0 ? -1 : 1;
    const absX = Math.abs(x) / Math.SQRT2;
    const t = 1.0 / (1.0 + p * absX);
    const erf = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-absX * absX);
    return 0.5 * (1.0 + sign * erf);
  }

  function update() {
    const S = parseFloat(sEl.value), K = parseFloat(kEl.value);
    const T = parseFloat(tEl.value), volPct = parseFloat(volEl.value), rPct = parseFloat(rEl.value);

    if (isNaN(S) || isNaN(K) || isNaN(T) || isNaN(volPct) || isNaN(rPct) || S <= 0 || K <= 0 || T <= 0 || volPct <= 0) return;

    const sigma = volPct / 100;
    const r = rPct / 100;

    // d1 = ( ln(S/K) + (r + sigma^2 / 2) * T ) / ( sigma * sqrt(T) )
    const d1 = (Math.log(S / K) + (r + (Math.pow(sigma, 2) / 2)) * T) / (sigma * Math.sqrt(T));
    // d2 = d1 - sigma * sqrt(T)
    const d2 = d1 - (sigma * Math.sqrt(T));

    const Nd1 = stdNormCdf(d1);
    const Nd2 = stdNormCdf(d2);
    const N_minus_d1 = stdNormCdf(-d1);
    const N_minus_d2 = stdNormCdf(-d2);

    // Call = S * Nd1 - K * exp(-r*T) * Nd2
    const callPrice = (S * Nd1) - (K * Math.exp(-r * T) * Nd2);
    // Put = K * exp(-r*T) * N(-d2) - S * N(-d1)
    const putPrice = (K * Math.exp(-r * T) * N_minus_d2) - (S * N_minus_d1);

    cResEl.textContent = '$' + callPrice.toFixed(2) + ' Call (Delta = ' + Nd1.toFixed(3) + ')';
    pResEl.textContent = '$' + putPrice.toFixed(2) + ' Put (Delta = ' + (Nd1 - 1).toFixed(3) + ')';
  }

  [sEl, kEl, tEl, volEl, rEl].forEach(el => el.addEventListener('input', update));
  update();
})();

