    thResEl.textContent = 'Bragg Angle θ = ' + theta_deg.toFixed(2) + '° | sin(θ) = ' + sin_theta.toFixed(4) + ' (2θ = ' + two_theta + '° @ λ = ' + lambda_ang + ' Å)';
  }

  [ttEl, lamEl, nEl].forEach(el => el.addEventListener('input', update));
