capillary-action-jurins-law-meniscus-hei.js:
(() => {
  'use strict';
  const rEl = document.getElementById('cap-r'), thEl = document.getElementById('cap-th'), gamEl = document.getElementById('cap-gam');
  const hResEl = document.getElementById('cap-res-ht'), lpResEl = document.getElementById('cap-res-lp');

  const g = 9.80665;
  const rho_water = 1000.0; // kg / m^3

  function update() {
    const rUm = parseFloat(rEl.value), thDeg = parseFloat(thEl.value), gamMnm = parseFloat(gamEl.value);
    if (isNaN(rUm) || isNaN(thDeg) || isNaN(gamMnm) || rUm <= 0 || gamMnm <= 0 || thDeg < 0 || thDeg > 180) return;

    const rM = rUm * 1e-6;
    const gamNm = gamMnm * 1e-3; // mN/m to N/m
    const thRad = (thDeg * Math.PI) / 180;

    // Jurin's law: h = (2 * gamma * cos(theta)) / (rho * g * r)  [meters]
    const hM = (2 * gamNm * Math.cos(thRad)) / (rho_water * g * rM);
    const hMm = hM * 1000;

    // Capillary Laplace suction pressure: deltaP = (2 * gamma * cos(theta)) / r  [Pa]
    const dP_Pa = (2 * gamNm * Math.cos(thRad)) / rM;

    let behavior = '';
    if (thDeg < 90) {
      behavior = 'Hydrophilic Capillary Rise (+Spontaneous Inflow Wicking)';
    } else if (thDeg === 90) {
      behavior = 'Neutral Meniscus (Zero Capillary Force)';
    } else {
      behavior = 'Hydrophobic Capillary Depression (Requires External Pressure to Enter)';
    }

    hResEl.textContent = 'h = ' + hMm.toFixed(1) + ' mm (' + (hMm / 10).toFixed(2) + ' cm Rise Height)';
    lpResEl.textContent = 'Laplace Suction: ' + Math.round(dP_Pa).toLocaleString() + ' Pa (' + (dP_Pa / 100).toFixed(1) + ' mbar) - ' + behavior;
  }

  [rEl, thEl, gamEl].forEach(el => el.addEventListener('input', update));
  update();
})();

capital-asset-pricing-model-sharpe-treyn.js:
(() => {
  'use strict';
  const rpEl = document.getElementById('cap-rp'), rfEl = document.getElementById('cap-rf');
  const rmEl = document.getElementById('cap-rm'), bEl = document.getElementById('cap-beta'), sdEl = document.getElementById('cap-sd');
  const alResEl = document.getElementById('cap-res-alpha'), rtResEl = document.getElementById('cap-res-ratios');

  function update() {
    const Rp = parseFloat(rpEl.value), Rf = parseFloat(rfEl.value);
    const Rm = parseFloat(rmEl.value), beta = parseFloat(bEl.value), sigma = parseFloat(sdEl.value);

    if (isNaN(Rp) || isNaN(Rf) || isNaN(Rm) || isNaN(beta) || isNaN(sigma) || sigma <= 0 || beta <= 0) return;

    // CAPM expected return: E(R) = Rf + beta * (Rm - Rf)
    const capm_expected = Rf + (beta * (Rm - Rf));

    // Jensen's Alpha: alpha = Rp - E(R)
    const alpha = Rp - capm_expected;

    // Sharpe Ratio = (Rp - Rf) / sigma
    const sharpe = (Rp - Rf) / sigma;

    // Treynor Ratio = (Rp - Rf) / beta
    const treynor = (Rp - Rf) / beta;

    alResEl.textContent = "Jensen's Alpha α = " + (alpha >= 0 ? '+' : '') + alpha.toFixed(2) + '%';
    alResEl.style.color = alpha >= 0 ? '#22543d' : '#c53030';
    rtResEl.textContent = 'Sharpe = ' + sharpe.toFixed(3) + ' | Treynor = ' + treynor.toFixed(2) + '% | CAPM Required Return = ' + capm_expected.toFixed(2) + '%';
  }

  [rpEl, rfEl, rmEl, bEl, sdEl].forEach(el => el.addEventListener('input', update));
  update();
})();

